const lv_img_dsc_t *source_icon_image(SourceIcon icon){
    switch(icon){
        case SourceIcon::Airplay:return &image_airplay;
        case SourceIcon::Analog:return &image_analog;
        case SourceIcon::Bluetooth:return &image_bluetooth;
        case SourceIcon::Cast:return &image_cast;
        case SourceIcon::Dlna:return &image_dlna;
        case SourceIcon::Hdmi:return &image_hdmi;
        case SourceIcon::Line:return &image_line;
        case SourceIcon::Network:return &image_network;
        case SourceIcon::Optical:return &image_optical;
        case SourceIcon::Roon:return &image_roon;
        case SourceIcon::Spotify:return &image_spotify;
        case SourceIcon::Tidal:return &image_tidal;
        case SourceIcon::Upnp:return &image_upnp;
        case SourceIcon::Unknown:return nullptr;
    }
    return nullptr;
}
